"""Generated by solo-to-scale; edit `templates/tools/tests/test_doctor.py` in the plugin, then run upgrade.

The doctor: what it finds in the repo and on GitHub, what --repair fixes, and the dashboard's Setup card.
"""
from __future__ import annotations

import datetime as dt
import json
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import build_dashboard as bd  # noqa: E402
import doctor  # noqa: E402
import heartbeat  # noqa: E402
from test_dashboard import NOW, data_of, root  # noqa: E402,F401

ALL_GATES = {"founders": [], "gates": {g: {"mode": "ask", "what": g, "paths": []}
                                       for g in ("hire", "budget", "deploy", "decision", "spend")}}


class Hub:
    """Just enough GitHub for the doctor."""
    def __init__(self, labels=(), runs=(), cost_comments=(), secrets=None) -> None:
        self.repo = "acme/example-startup"
        self.labels = [{"name": n} for n in labels]
        self.runs, self.cost_comments, self.secrets = list(runs), list(cost_comments), secrets
        self.calls: list[tuple] = []

    def tickets(self, state="open", label="ticket"):
        return [{"number": 50, "title": f"Cost log {NOW:%Y-%m}"}] if label == heartbeat.COST_LOG and self.cost_comments else []

    def api(self, path, *args, payload=None):
        self.calls.append((path, args, payload))
        if path.startswith("labels") and "-X" in args:
            self.labels.append({"name": payload["name"]})
            return payload
        if path.startswith("labels"):
            return self.labels
        if path.startswith("issues/50/comments"):
            return self.cost_comments
        if path.startswith("actions/workflows/dashboard.yml/runs"):
            return {"workflow_runs": self.runs}
        if path.startswith("actions/secrets"):
            if self.secrets is None:
                raise ValueError("403")
            return {"secrets": [{"name": n} for n in self.secrets]}
        raise AssertionError(path)


def by_key(found):
    return {x["key"]: x for x in found}


def workflows(root: Path) -> None:
    wf = root / ".github" / "workflows"
    wf.mkdir(parents=True, exist_ok=True)
    for name in doctor.WORKFLOWS:
        (wf / name).write_text("name: x\n", encoding="utf-8")


def test_a_fresh_repo_lists_what_is_broken_and_what_is_to_do(root):
    found = by_key(doctor.run(root, offline=True, now=NOW))
    assert found["project"]["status"] == "ok"
    assert found["workflows"]["status"] == "broken" and "dashboard.yml" in found["workflows"]["detail"]
    assert found["gates"]["status"] == "broken" and "founder/goals.json (decision)" in found["gates"]["detail"]
    assert found["goal"]["status"] == "todo" and found["goal"]["repair"] == "goals"
    assert found["budgets"]["status"] == "ok", "the fixture's engineer is on with a budget"
    assert found["hosting"]["status"] == "info", "not hosting yet is fine: the Claude page is the backup"
    assert "labels" not in found, "offline checks the repo only"
    statuses = [x["status"] for x in doctor.run(root, offline=True, now=NOW)]
    assert statuses == sorted(statuses, key=doctor.STATUSES.index), "broken first"
    assert doctor.main(["--offline", "--root", str(root)]) == 1


def test_repair_gates_the_founder_files_and_writes_an_empty_goal(root, capsys):
    (root / "founder" / "gates.json").write_text(json.dumps(ALL_GATES), encoding="utf-8")
    workflows(root)
    assert doctor.main(["--offline", "--repair", "--root", str(root)]) == 0
    out = capsys.readouterr().out
    assert "repaired: wrote an empty founder/goals.json" in out and "founder/goals.json → decision" in out
    gates = json.loads((root / "founder" / "gates.json").read_text(encoding="utf-8"))["gates"]
    assert all(rel in gates[g]["paths"] for rel, g in doctor.GATED.items())
    found = by_key(doctor.run(root, offline=True, now=NOW))
    assert found["gates"]["status"] == "ok" and found["goal"]["status"] == "todo", "the goal itself is the founder's"
    assert found["objectives"]["status"] == "todo"


def test_a_role_on_without_a_budget_is_broken(root):
    p = root / "founder" / "heartbeats.json"
    pol = json.loads(p.read_text(encoding="utf-8"))
    pol["roles"]["qa"] = {"enabled": True, "cron": "0 9 * * *", "monthly_budget_usd": None}
    p.write_text(json.dumps(pol), encoding="utf-8")
    assert by_key(doctor.run(root, offline=True, now=NOW))["budgets"]["status"] == "broken"


def test_hosting_secrets_are_checked_by_whether_they_are_set(root, monkeypatch):
    (root / "founder" / "dashboard.json").write_text(json.dumps({"host": "pm.example.com",
                                                                 "cloudflare_pages_project": "example-pm"}), encoding="utf-8")
    assert by_key(doctor.run(root, offline=True, now=NOW))["hosting"]["status"] == "unknown"
    monkeypatch.setenv("S2S_HAS_CLOUDFLARE_API_TOKEN", "false")
    monkeypatch.setenv("S2S_HAS_CLOUDFLARE_ACCOUNT_ID", "true")
    h = by_key(doctor.run(root, offline=True, now=NOW))["hosting"]
    assert h["status"] == "broken" and "CLOUDFLARE_API_TOKEN" in h["detail"] and "ACCOUNT_ID" not in h["detail"]
    monkeypatch.setenv("S2S_HAS_CLOUDFLARE_API_TOKEN", "true")
    assert by_key(doctor.run(root, offline=True, now=NOW))["hosting"]["status"] == "ok"
    monkeypatch.delenv("S2S_HAS_CLOUDFLARE_API_TOKEN")
    monkeypatch.delenv("S2S_HAS_CLOUDFLARE_ACCOUNT_ID")
    found = by_key(doctor.run(root, now=NOW, hub=Hub(secrets=["CLOUDFLARE_API_TOKEN"])))
    assert found["hosting"]["status"] == "broken", "locally, the names come from the GitHub API"
    (root / "founder" / "portfolio.json").write_text(json.dumps({"ventures": [{"repo": "acme/other"}]}), encoding="utf-8")
    assert by_key(doctor.run(root, now=NOW, hub=Hub(secrets=[])))["portfolio"]["status"] == "broken"


def test_github_labels_runs_and_the_dashboard_build(root):
    old = (NOW - dt.timedelta(days=5)).strftime("%Y-%m-%dT%H:%M:%SZ")
    cost = {"body": heartbeat.cost_entry("engineer", 1.0, f"{NOW:%Y-%m}", "measured", None, "run"), "created_at": old}
    hub = Hub(labels=["ticket"], runs=[{"status": "completed", "conclusion": "failure", "updated_at": old,
                                        "html_url": "https://github.com/acme/example-startup/actions/runs/1"}],
              cost_comments=[cost], secrets=[])
    found = by_key(doctor.run(root, now=NOW, hub=hub))
    assert found["labels"]["status"] == "todo" and "claimed" in found["labels"]["detail"]
    assert found["runs"]["status"] == "todo" and "engineer" in found["runs"]["detail"], "no run in 72h"
    assert found["dashboard_run"]["status"] == "broken" and "actions/runs/1" in found["dashboard_run"]["fix"]
    done = doctor.repair(root, list(found.values()), hub)
    assert "created label claimed" in done and {lb["name"] for lb in hub.labels} >= set(doctor.LABELS)
    cost["created_at"] = NOW.strftime("%Y-%m-%dT%H:%M:%SZ")
    hub.runs[0]["conclusion"] = "success"
    found = by_key(doctor.run(root, now=NOW, hub=hub))
    assert found["labels"]["status"] == found["runs"]["status"] == found["dashboard_run"]["status"] == "ok"


def test_github_trouble_is_unknown_never_a_crash(root):
    class Down(Hub):
        def api(self, path, *args, payload=None):
            raise ValueError("unreachable")

        def tickets(self, state="open", label="ticket"):
            raise ValueError("unreachable")
    found = by_key(doctor.run(root, now=NOW, hub=Down()))
    assert found["labels"]["status"] == found["runs"]["status"] == found["dashboard_run"]["status"] == "unknown"


def test_the_dashboard_shows_the_setup_card(root):
    d = data_of(bd.page(bd.build(root, offline=True, now=NOW)))
    keys = {x["key"]: x["status"] for x in d["setup"]}
    assert keys["gates"] == "broken" and keys["goal"] == "todo"
    page = bd.PAGE.read_text(encoding="utf-8")
    assert "function setupPanel" in page and "setupPanel()," in page
    wf = (Path(__file__).resolve().parents[2] / ".github" / "workflows" / "dashboard.yml")
    if wf.exists():  # in the plugin; a startup repo has it at the same place
        text = wf.read_text(encoding="utf-8")
        assert "S2S_HAS_CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN != '' }}" in text
        assert "actions: read" in text


def test_the_setup_card_survives_a_broken_check(root, monkeypatch):
    def boom(*a, **k):
        raise RuntimeError("bug")
    monkeypatch.setattr(doctor, "run", boom)
    assert bd.build(root, offline=True, now=NOW)["setup"][0]["status"] == "unknown"
